edits.before:
protected override _getShowOptions(): { modal: boolean, preventBodyScroll: boolean } {
  const useModal = Boolean(this._config.backdrop) || !this._config.scroll
  return {
    modal: useModal,
    preventBodyScroll: !this._config.scroll
  }
}

edits.after:
protected override _getShowOptions(): { modal: boolean, preventBodyScroll: boolean } {
  return {
    modal: false,
    preventBodyScroll: !this._config.scroll
  }
}
